using RansomFree.Contracts;
using RansomFree.Server;
var root=Path.Combine(@"D:\Codex\RansomFree\W-SQ07\tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var checks=new List<string>();
void Check(bool value,string name){if(!value)throw new Exception(name);checks.Add("PASS: "+name);Console.WriteLine(checks[^1]);File.WriteAllLines(Path.Combine(root,"results.txt"),checks);}
void Reject(Action action,string name){try{action();}catch(Exception e)when(e is DecoyJobConflictException or ArgumentException or KeyNotFoundException){Check(true,name);return;}throw new Exception(name);}
var store=new Store(root);store.InitializeDecoyJobs();
var endpoint=store.Enroll(new(store.CreateCode().Code,"SQ07 isolated fixture","0.6.4-dev"))!;
var other=store.Enroll(new(store.CreateCode().Code,"SQ07 other fixture","0.6.4-dev"))!;
var sid="S-1-5-21-100-200-300-1001";
var definition=new DecoySessionJob(Guid.NewGuid().ToString("N"),sid,@"D:\Synthetic\State",@"D:\Synthetic\Decoys","create",Guid.NewGuid().ToString("N"),"V02","Payroll","X:");
var body=new ApproveDecoyJob(endpoint.EndpointId,definition,"");var job=store.ApproveDecoy(body,"fixture-admin");
Check(new Store(root).ApproveDecoy(body,"fixture-admin")==job,"approval retry survives restart without new revision");
Reject(()=>store.ApproveDecoy(body with{Job=definition with{Name="Changed"}},"fixture-admin"),"conflicting job identity preserved");
Reject(()=>store.ApproveDecoy(body with{EndpointId=other.EndpointId},"fixture-admin"),"job cannot move to another endpoint");
Check(store.PollDecoyJobs(other.EndpointId).Assignment==null,"unassigned endpoint cannot download work");
var offers=await Task.WhenAll(Enumerable.Range(0,8).Select(_=>Task.Run(()=>new Store(root).PollDecoyJobs(endpoint.EndpointId))));
Check(offers.All(o=>o.Assignment==job),"eight concurrent polls receive one immutable assignment");
Check(store.DecoyJobsHistory().Single().State=="Offered","offer persisted before delivery");
var next=store.ApproveDecoy(body with{Job=definition with{JobId=Guid.NewGuid().ToString("N"),Action="activate",ExpectedRevision=1}},"fixture-admin");
Check(store.PollDecoyJobs(endpoint.EndpointId).Assignment==job,"later mutation waits behind outstanding job");
var receipt=new DecoyJobReport(definition.JobId,job.PolicyRevision,sid,1,"0000000000000001",new(definition.JobId,new string('A',64),"Applied",1,"Disabled"));
Reject(()=>store.ReceiveDecoyReport(other.EndpointId,receipt),"receipt cannot cross endpoint");
Reject(()=>store.ReceiveDecoyReport(endpoint.EndpointId,receipt with{PolicyRevision=99}),"receipt cannot cross policy revision");
var ack=store.ReceiveDecoyReport(endpoint.EndpointId,receipt);
Check(new Store(root).ReceiveDecoyReport(endpoint.EndpointId,receipt)==ack,"receipt retry preserves reconciliation challenge after restart");
Reject(()=>store.ReceiveDecoyReport(endpoint.EndpointId,receipt with{Receipt=receipt.Receipt with{State="Failed"}}),"conflicting result cannot overwrite evidence");
Check(store.DecoyJobsHistory().Single(x=>x.JobId==definition.JobId).Observation==null,"action receipt never manufactures native observation");
Check(store.PollDecoyJobs(endpoint.EndpointId).Assignment==job,"receipt alone does not release next mutation");
var observation=new DecoyNativeReport(definition.JobId,definition.DecoyId,job.PolicyRevision,sid,1,receipt.LogonId,ack.Challenge,DateTimeOffset.UtcNow,1,"Disabled");
Reject(()=>store.ReceiveDecoyObservation(endpoint.EndpointId,observation with{Challenge=new string('B',64)}),"unissued observation challenge refused");
Reject(()=>store.ReceiveDecoyObservation(endpoint.EndpointId,observation with{UserSid="S-1-5-21-100-200-300-1002"}),"observation cannot change assigned user");
Reject(()=>store.ReceiveDecoyObservation(endpoint.EndpointId,observation with{Scope="SYSTEM attestation"}),"SYSTEM promotion refused");
Reject(()=>store.ReceiveDecoyObservation(endpoint.EndpointId,observation with{ObservedUtc=DateTimeOffset.UtcNow.AddHours(1)}),"future observation refused");
store.ReceiveDecoyObservation(endpoint.EndpointId,observation);new Store(root).ReceiveDecoyObservation(endpoint.EndpointId,observation);
Check(store.DecoyJobsHistory().Single(x=>x.JobId==definition.JobId).State=="Reconciled","matching separately challenged observation persisted");
Reject(()=>store.ReceiveDecoyObservation(endpoint.EndpointId,observation with{State="Active"}),"conflicting observation preserved");
Check(store.PollDecoyJobs(endpoint.EndpointId).Assignment==next,"completed reconciliation releases subsequent explicit approval");
Check(store.DecoyJobsHistory().Count==2,"all jobs and original reports retained");
Console.WriteLine(root);
var localPath=Path.Combine(root,"broker");Directory.CreateDirectory(localPath);var local=new DecoyJobLocalStore(localPath,endpoint.EndpointId);local.Cache(job);local.Cache(job);
Check(local.Current()?.Job==job,"local cache retains exact approval across retries");
var poll=local.Handle(sid,1,"0000000000000001",new("job-poll"));
Check(poll.Assignment?.Job==job.Job,"managed local job reaches existing nonce-bound broker");
var restarted=new DecoyJobLocalStore(localPath,endpoint.EndpointId);
Check(restarted.Handle(sid,1,"0000000000000001",new("job-poll")).Assignment==poll.Assignment,"offline broker restart retains nonce and deadline");
var localReceipt=new DecoySessionReceipt(job.Job.JobId,poll.Assignment!.Nonce,"Applied",1,"Disabled");
Check(local.Handle(sid,1,"0000000000000001",new("job-receipt",localReceipt)).State=="Session result recorded","receipt durably queued while central server offline");
Check(restarted.Report(job)?.Receipt==localReceipt,"receipt recovered directly from ledger after restart without outbox gap");
Check(restarted.Handle(sid,1,"0000000000000001",new("job-poll")).State=="Receipt queued","no native observation synthesized while offline");
local.SetChallenge(job,ack.Challenge);var reconcile=restarted.Handle(sid,1,"0000000000000001",new("job-poll"));
Check(reconcile.State=="Reconcile"&&reconcile.Assignment==null,"later reconciliation challenge cannot execute an action");
Check(local.Handle(sid,1,"0000000000000001",new("job-observation",Observation:observation)).State=="Observation queued","native observation durably queued offline");
Check(restarted.Current()?.Observation==observation,"observation bytes survive restart for exact upload retry");
local.Acknowledge(job);local.Cache(next);Check(local.Current()?.Job==next,"acknowledged history retained when next approved job is downloaded");
var nativePath=Path.Combine(root,"native");var nativeState=Path.Combine(nativePath,"state");var nativeTargets=Path.Combine(nativePath,"targets");Directory.CreateDirectory(nativeState);Directory.CreateDirectory(nativeTargets);
var engine=new RansomFree.WindowsDecoys.VirtualDecoys(nativeState,nativeTargets);var nativePlan=new RansomFree.WindowsDecoys.VirtualDecoyPlan(Guid.NewGuid().ToString("N"),"V03","SQ07 fixture library");var created=engine.Create(nativePlan);
var nativeBefore=File.ReadAllBytes(Path.Combine(nativeState,"virtual-decoys.db"));var nativeObservation=RansomFree.WindowsDecoys.DecoyReconciliation.Observe(nativeState,nativeTargets,nativePlan);
Check(nativeObservation.State=="Disabled"&&nativeObservation.Revision==created.Revision,"fresh native reconciliation observes isolated V03 resource");
Check(nativeBefore.AsSpan().SequenceEqual(File.ReadAllBytes(Path.Combine(nativeState,"virtual-decoys.db"))),"native reconciliation preserves inventory bytes and revision");
Check(Directory.Exists(created.Target),"native reconciliation retains backing decoy and marker");
local.Handle(sid,1,"0000000000000001",new("job-poll"));
Check(restarted.Handle(sid,2,"0000000000000002",new("job-poll")).State=="Interrupted job queued for review","new logon seals interruption without replay");
var interrupted=restarted.Report(next)!;Check(interrupted.Receipt.State=="Unconfirmed"&&interrupted.Origin=="Broker interruption"&&interrupted.SessionId==1,"interruption origin and original assignment identity survive restart");
var interruptedAck=store.ReceiveDecoyReport(endpoint.EndpointId,interrupted);local.SetChallenge(next,interruptedAck.Challenge);
var afterLogon=local.Handle(sid,2,"0000000000000002",new("job-poll"));Check(afterLogon.State=="Reconcile"&&afterLogon.SessionId==2&&afterLogon.Assignment==null,"new session receives read-only check rather than original action");
var unavailable=new DecoyNativeReport(next.Job.JobId,next.Job.DecoyId,next.PolicyRevision,sid,2,"0000000000000002",interruptedAck.Challenge,DateTimeOffset.UtcNow,null,"Unavailable");
try{local.Handle(sid,1,"0000000000000001",new("job-observation",Observation:unavailable));throw new Exception("spoof accepted");}catch(InvalidDataException){Check(true,"broker rejects observation carrying another live session identity");}
local.Handle(sid,2,"0000000000000002",new("job-observation",Observation:unavailable));store.ReceiveDecoyObservation(endpoint.EndpointId,unavailable);
Check(store.DecoyJobsHistory().Single(x=>x.JobId==next.Job.JobId).State=="Needs review","unavailable native check preserves uncertainty");
var queued=store.ApproveDecoy(body with{Job=definition with{JobId=Guid.NewGuid().ToString("N"),Action="observe"}},"fixture-admin");
Check(store.PollDecoyJobs(endpoint.EndpointId).Assignment==null,"unresolved uncertainty holds all later queued jobs");
var review=new ReviewDecoyJob(endpoint.EndpointId,next.Job.JobId,next.PolicyRevision,DecoyJobsProtocol.Digest(unavailable),"Fixture reviewed; no replay authorized","");
Reject(()=>store.ReviewDecoy(review with{ObservationDigest=new string('0',64)},"fixture-admin"),"stale review cannot release queue");
store.ReviewDecoy(review,"fixture-admin");store.ReviewDecoy(review,"fixture-admin");Check(store.PollDecoyJobs(endpoint.EndpointId).Assignment==queued,"explicit evidence-bound review releases queue idempotently");
Check(store.DecoyJobEvents(next.Job.JobId).Length==5,"approval assignment receipt observation review retained in ordered history");
var expiredRoot=Path.Combine(root,"expired");Directory.CreateDirectory(expiredRoot);var expiredLocal=new DecoyJobLocalStore(expiredRoot,endpoint.EndpointId);var expired=job with{ApprovedUtc=DateTimeOffset.UtcNow.AddDays(-2),ExpiresUtc=DateTimeOffset.UtcNow.AddDays(-1)};expiredLocal.Cache(expired);
Check(expiredLocal.Handle(sid,1,"0000000000000001",new("job-poll")).State=="Interrupted job queued for review","expired unstarted local approval records uncertainty without dispatch");
Check(expiredLocal.Report(expired)?.Receipt.State=="Unconfirmed","expired unstarted job has durable report for central recovery");

